// Generated by scripts/build-guide-content.js from CLPeasy's own pages — do not edit by hand.
// Re-run `node scripts/build-guide-content.js` after changing the Help Guide, FAQ, Knowledge Base,
// printing guide, support, compliance or combining-oils pages.
(function (root) {
  var content = { cards: [
    {"id":"help-before-you-start","title":"Before you start","html":"<p>You will need your fragrance supplier's SDS (Safety Data Sheet) PDF. Find it on your supplier's product page.</p><p>Tip: Have your SDS PDF open in another tab before you start — you will need to copy from Section 2.2.</p>","source":"builder-help","links":[],"keywords":""},
    {"id":"help-step-1-label","title":"Step 1 — Label","html":"<ol><li>Choose the label shape, then enter the size you need in millimetres.</li><li>Choose the label colours and border appearance.</li></ol>","source":"builder-help","links":[],"keywords":""},
    {"id":"help-step-2-product","title":"Step 2 — Product","html":"<ol><li>Enter the product name and select the product type.</li><li>Add the optional weight, fragrance load and burn time details.</li></ol>","source":"builder-help","links":[],"keywords":""},
    {"id":"help-step-3-hazards","title":"Step 3 — Hazards","html":"<ol><li>Select your fragrance supplier and open the current SDS.</li><li>Paste <strong>Section 2.2 — Label elements</strong> into Smart Paste.</li><li>Check every extracted code, pictogram and sensitiser against the SDS.</li></ol>","source":"builder-help","links":[],"keywords":""},
    {"id":"help-step-4-business","title":"Step 4 — Business","html":"<ol><li>Enter the required business and contact details.</li><li>Add the optional website and batch number.</li></ol>","source":"builder-help","links":[],"keywords":""},
    {"id":"help-step-5-download","title":"Step 5 — Download","html":"<ol><li>Review your label in the preview carefully.</li><li><strong>Tick the verification checkbox</strong> to confirm you have checked all data against your SDS.</li><li>Download PNG, PDF or SVG only when the complete label passes the fit check.</li><li>Click <strong>Save to my label library</strong> to save this label in your current browser for future use on this device.</li></ol><p>The dashed line is the cut guide border. It marks the outline of your label shape and is part of the downloaded label, so it <strong>does print</strong>. You can turn it off in Step 1 with <strong>Hide border</strong>.</p>","source":"builder-help","links":[],"keywords":""},
    {"id":"help-printing-a-single-label","title":"Printing a single label","html":"For a single label, download <strong>PDF</strong> in Step 5 and click <strong>Print / Save as PDF</strong>. In the print settings choose <strong>Actual Size</strong> or <strong>100%</strong>, and turn off <strong>Fit to page</strong>, <strong>Shrink</strong> or <strong>Scale to fit</strong>. The exact wording varies between browsers, PDF viewers and printers.","source":"builder-help","links":[],"keywords":""},
    {"id":"help-printing-a-sheet-of-labels","title":"Printing a sheet of labels","html":"For several labels on A4, save each label, then open the <strong>Print Sheet Composer</strong> and choose how many of each you need. It keeps every label at its saved size and lays them out on A4. Set your printer to <strong>A4</strong> paper and print at <strong>Actual Size / 100%</strong>, not Fit to page or Shrink.","source":"builder-help","links":[],"keywords":"a4 sheet several many labels composer"},
    {"id":"help-choosing-a-file-format","title":"Choosing a file format","html":"<strong>PDF</strong>: an individual label file at its exact size, for printing a single label. For several labels on A4, use the <strong>Print Sheet Composer</strong>. <strong>SVG</strong>: keeps the size in millimetres, for design and cutting-machine software. <strong>PNG</strong>: a high-resolution image; it doesn't store a print size, so the app you print it from may choose its own size.","source":"builder-help","links":[],"keywords":""},
    {"id":"help-first-print-check","title":"First print check","html":"The first time you print, use ordinary paper and measure one label with a ruler. It should match the size shown in CLPeasy. For a sheet, also hold the test print against your label sheet to check the labels line up before using your label stock.","source":"builder-help","links":[],"keywords":""},
    {"id":"help-my-label-printed-too-large-or-too-small","title":"My label printed too large or too small","html":"Check the print scale is <strong>Actual Size / 100%</strong> and that Fit to page, Shrink or Scale to fit is turned off. If you printed a PNG, use PDF (single label) or the Print Sheet Composer (several labels on A4) instead for a more reliable printed size.","source":"builder-help","links":[],"keywords":"wrong size too big too small scale shrunk"},
    {"id":"help-my-sheet-doesn-t-line-up-with-my-label-sheet","title":"My sheet doesn't line up with my label sheet","html":"Check the printer's paper size is A4 and the scale is Actual Size / 100%, then test on ordinary paper again. CLPeasy creates the file at the correct size, but your browser, PDF viewer and printer settings can still change how it prints.","source":"builder-help","links":[],"keywords":""},
    {"id":"help-where-do-i-find-my-sds-sheet","title":"Where do I find my SDS sheet?","html":"On your fragrance supplier's website — usually on the individual product page. Look for a Download SDS or Safety Data Sheet link. Contact your supplier if you can't find it.","source":"builder-help","links":[],"keywords":"sds safety data sheet find supplier download"},
    {"id":"help-what-is-euh208","title":"What is EUH208?","html":"EUH208 means \"Contains [substance name] — may produce an allergic reaction.\" You need it if your fragrance contains certain sensitiser substances above the threshold level. Your SDS Section 2.2 will tell you if it applies.","source":"builder-help","links":[],"keywords":"euh208 allergen allergy sensitiser contains"},
    {"id":"help-what-size-label-should-i-use","title":"What size label should I use?","html":"CLPeasy supports circle and square labels from 52mm, and rectangles from 52mm on the long side and 36mm on the short side. This is a CLPeasy minimum, not a universal GB CLP legal label-size rule — the space needed depends on the required information. 63mm suits many larger jars. The Builder checks that everything fits at a readable size before you can download.","source":"builder-help","links":[],"keywords":"size small wax melt clamshell 52mm 63mm minimum diameter"},
    {"id":"help-smart-paste-didn-t-extract-everything-correctly","title":"Smart Paste didn't extract everything correctly","html":"Make sure you copied the complete Section 2.2 from your supplier's current SDS, then extract again. Hazard and precautionary statements come only from Smart Paste and can't be chosen or typed in by hand. If the result still doesn't match your SDS, don't use the label. Contact support.","source":"builder-help","links":[],"keywords":"smart paste missing extract wrong"},
    {"id":"help-can-i-use-this-on-my-phone","title":"Can I use this on my phone?","html":"Yes — CLPeasy works on iPhone and Android. PNG files save to your camera roll and SVG files save to your Files app.","source":"builder-help","links":[],"keywords":"phone mobile iphone android tablet"},
    {"id":"help-what-s-the-difference-between-pay-as-you-go-and-easy-start-u","title":"What's the difference between Pay As You Go and Easy Start Unlimited?","html":"Pay As You Go is a one-off £4.99 pack of downloads (5 + 3 free during the 2026 launch offer) that never expire — buy another pack whenever you need more. Easy Start Unlimited gives you unlimited downloads while you're subscribed: £9.99/month (£8.99/month until 31 December 2026) or £89/year. Both give clean, watermark-free labels, the full label builder and A4 print sheets. Every account starts with a 14-day free trial — no card needed.","source":"builder-help","links":[],"keywords":""},
    {"id":"faq-what-is-a-clp-label-and-do-i-need-one","title":"What is a CLP label and do I need one?","html":"<p>Whether a GB CLP label is needed depends on your finished formulation and the applicable classification and supplemental labelling rules. Check appropriate finished-product information before supplying your product. Our <a href=\"compliance.html\">Compliance &amp; Transparency page</a> explains how CLPeasy supports label creation.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":"do i need a clp label wax melts candles diffusers sprays need one"},
    {"id":"faq-what-products-does-clpeasy-support","title":"What products does CLPeasy support?","html":"<p>CLPeasy is designed for GB CLP label creation for candles, wax melts, reed diffusers and room sprays using suitable SDS documentation. It is not a finished-cosmetics labelling tool. Bath bombs and soaps that are finished cosmetic products intended for the final user follow the applicable cosmetics rules.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-is-clpeasy-recognised-or-approved-by-hse","title":"Is CLPeasy recognised or approved by HSE?","html":"<p>No. Contact with the HSE Helpdesk does not constitute approval or certification of CLPeasy, its labels or customers’ products. Read our <a href=\"compliance.html\">Compliance &amp; Transparency page</a> for the correspondence summary.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-who-is-responsible-for-a-gb-clp-label","title":"Who is responsible for a GB CLP label?","html":"<p>HSE describes manufacturers, importers, downstream users and distributors that place chemicals on the Great Britain market as <strong>suppliers</strong>, with duties depending on their role in the supply chain. Makers who formulate mixtures can be downstream users and have duties to classify, label and package those mixtures before placing them on the GB market.</p> <p>CLPeasy supports the practical label-building process by extracting, organising, checking and formatting the information you provide. You still need to review the finished label and make sure the source information and classification are appropriate for the product you place on the market.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-i-make-bath-bombs-and-soaps-do-i-need-a-clp-label","title":"I make bath bombs and soaps — do I need a CLP label?","html":"<p>Finished cosmetic products intended for the final user are outside GB CLP scope.</p> <p>If a bath bomb, soap or other product is a <strong>cosmetic product in its finished state intended for the final user</strong>, HSE states that GB CLP does not apply to that finished cosmetic. Cosmetic products are instead subject to the applicable cosmetics rules.</p> <strong>CLPeasy is not a cosmetic-labelling tool.</strong><br><br> CLPeasy is designed for GB CLP hazard labels for products within GB CLP scope. If your product is a cosmetic, use the applicable cosmetics requirements and OPSS guidance rather than relying on a CLPeasy CLP label for the finished cosmetic. <p>If you are unsure, consult the <a href=\"https://www.gov.uk/guidance/submit-a-cosmetic-product-notification\" target=\"_blank\" rel=\"noopener\">OPSS guidance on cosmetic products</a> or speak with a qualified cosmetic safety assessor.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-does-clpeasy-classify-my-finished-product","title":"Does CLPeasy classify my finished product?","html":"<p>No. CLPeasy extracts and formats label information from suitable SDS documentation. It does not independently classify finished mixtures or recalculate hazards when you enter a fragrance percentage.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-how-do-i-print-my-labels-at-home","title":"How do I print my labels at home?","html":"<p>Choose your route in <a href=\"printing-and-cutting.html\">Print your labels</a>: one label, an A4 sheet, PDF, PNG, Cricut, phone/tablet or a print company. Each guide includes visual steps and a final print checklist.</p><p>For printer types, red pictogram borders, materials, sizing and troubleshooting, see <a href=\"printing-and-cutting.html#faq\">Printing questions answered</a>.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-where-do-i-find-the-hazard-classification-data-for-my-fragra","title":"Where do I find the hazard classification data for my fragrance?","html":"<p>Safety Data Sheets are required under UK REACH in specified circumstances, including for hazardous chemicals supplied for use at work and some mixtures containing hazardous substances. Where an SDS is supplied, <strong>Section 2.2</strong> contains the label elements for that supplied chemical or mixture.</p> <p>For CLPeasy, use the current supplier information that is applicable to your finished product and fragrance load. Smart Paste lets you paste the relevant Section 2.2 text and extracts available label information for you to review.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-can-i-save-and-reuse-my-labels","title":"Can I save and reuse my labels?","html":"<p>Yes. CLPeasy lets you save labels to your browser-based library and reload them on the same device. This means once you have set up a product, generating a new label or reprinting an existing one takes seconds.</p> <p>We recommend reviewing your saved labels whenever your fragrance supplier updates their SDS, as hazard classifications can change between batches or supplier reformulations.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-can-i-use-more-than-one-fragrance-oil-or-essential-oil","title":"Can I use more than one fragrance oil or essential oil?","html":"<p>You need appropriate information for the whole finished formulation. CLPeasy cannot combine SDSs or calculate a custom blend's classification. Read <a href=\"combining-fragrance-oils.html\">Combining fragrance oils: where to start</a> before preparing the label.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-which-sds-should-i-use","title":"Which SDS should I use?","html":"<p>Use current SDS documentation confirmed as applicable to your product type, formulation, concentration and the GB market. An SDS for concentrated oil or a different product base is not automatically suitable. Smart Paste reads the complete Section 2.2.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-can-i-use-a-10-sds-for-a-lower-fragrance-load","title":"Can I use a 10% SDS for a lower fragrance load?","html":"<p>Do not assume a higher-concentration SDS is automatically appropriate. Ask the document provider to confirm whether it covers your actual finished formulation. CLPeasy does not calculate or validate a different concentration for you.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-can-i-type-in-a-classification-report-or-correct-hazard-stat","title":"Can I type in a classification report or correct hazard statements myself?","html":"<p>No. Hazard and precautionary statements come only from Smart Paste extraction of your supplier's SDS; the Builder does not allow manual hazard entry or overrides. Labels saved before this change can still be printed, duplicated and resized, with their hazard information locked. If the result differs from your SDS, contact support before using the label.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-does-a-clpeasy-label-mean-my-candle-has-passed-safety-testin","title":"Does a CLPeasy label mean my candle has passed safety testing?","html":"<p>No. Label creation does not test a candle's burning behaviour or establish product safety. See our <a href=\"combining-fragrance-oils.html\">blending and candle-safety article</a> for the distinction and links to GB guidance.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-when-should-i-contact-support","title":"When should I contact support?","html":"<p>Whenever you need help using CLPeasy, including Smart Paste, layout, printing, downloads or your account. Michaela replies personally. For classification decisions or product testing, you will need appropriate help outside CLPeasy's software support.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-what-is-included-in-the-free-trial","title":"What is included in the free trial?","html":"<p>Your 14-day free trial gives you full access to CLPeasy — build labels, save them in your browser-based library, and test the download workflow with up to 10 watermarked downloads. No card or payment details are required to start. When the trial ends, you can buy Pay As You Go downloads or choose an Easy Start Unlimited subscription.</p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"faq-what-is-the-difference-between-pay-as-you-go-and-easy-start-","title":"What is the difference between Pay As You Go and Easy Start Unlimited?","html":"<p><strong>Pay As You Go</strong> is for occasional downloads with no subscription. £4.99 buys 8 downloads — includes 3 bonus downloads with every pack until 31 December 2026 (5 downloads per pack from 1 January 2027). Purchased downloads do not expire, and you can buy another PAYG pack whenever you need more.</p> <p><strong>Easy Start Unlimited</strong> is a subscription with unlimited downloads while it is active. It is £9.99/month, with a 2026 offer of £8.99/month until 31 December 2026; or £89/year (save £30.88 compared with paying £9.99 monthly).</p> <p>Both options use the same label builder, Smart Paste, browser-saved label library, Print Sheet Composer and Cricut download tools.</p> <p>Not sure which option suits you? <a href=\"plan-picker.html\">Try our quick option finder →</a></p>","source":"faq","links":[{"href":"faq.html","label":"FAQ"}],"keywords":""},
    {"id":"print-which-printer-should-i-use","title":"Which printer should I use?","html":"<p>A colour inkjet or colour laser can be a practical home-printing choice. Use label stock specifically compatible with your printer. For Cricut Print Then Cut, Cricut recommends inkjet for its wider printable-material options; laser printers need stock made to withstand their heat. There is no universal “best” printer for every material.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":"printer buy best inkjet laser"},
    {"id":"print-is-home-printing-allowed-under-gb-clp","title":"Is home printing allowed under GB CLP?","html":"<p>GB CLP sets requirements for the finished labelling rather than naming a compulsory printer. Information must be clear, indelible, easy to read and firmly attached, with the applicable label and pictogram dimensions. Home printing can meet those requirements; a good-looking print alone does not establish that the contents are correct.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-does-the-whole-pictogram-have-to-be-red","title":"Does the whole pictogram have to be red?","html":"<p>No. Where a hazard pictogram is required, its diamond border is red, its symbol is black and its background is white. Do not switch the finished file to black-and-white or greyscale. The whole label does not need decorative colour.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-use-a-thermal-label-printer","title":"Can I use a thermal label printer?","html":"<p>Thermal printing is not automatically prohibited. A black-only printer on blank white stock cannot create a required red pictogram border. Correctly preprinted colour stock is a possible configuration only if the complete print is accurately aligned and suitable. Direct thermal stock can also react to heat, light and chemicals; material performance needs checking. Thermal transfer is a different process.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-do-i-have-to-buy-vinyl-or-waterproof-labels","title":"Do I have to buy vinyl or waterproof labels?","html":"<p>GB CLP does not name one compulsory label material. Choose a printer-compatible material and adhesive suitable for the package and its normal conditions. A diffuser bottle exposed to drips may need a different material from a dry outer box. “Waterproof” does not automatically mean resistant to fragrance oil, alcohol, rubbing or heat.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-use-a-laser-printer-for-stickers","title":"Can I use a laser printer for stickers?","html":"<p>Use only printable stock that its manufacturer identifies as laser-compatible, together with your printer’s permitted media settings. Do not feed inkjet-only vinyl or other heat-sensitive stock through a laser printer. Follow both the stock supplier’s and printer manufacturer’s instructions.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-what-is-the-easiest-file-for-ordinary-printing","title":"What is the easiest file for ordinary printing?","html":"<p>For a single label, use the Builder’s PDF print view. For a positioned A4 sheet, use Print Sheet Composer and its Print / Save as PDF control. Use PNG or SVG when a specific design/cutting workflow needs them. Check printed dimensions whichever route you use.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-why-has-pdf-opened-a-tab-instead-of-downloading","title":"Why has PDF opened a tab instead of downloading?","html":"<p>The current Builder PDF control opens a print view. Select Print / Save as PDF in that view. Choose a real printer to print immediately, or a PDF destination to save a file. Printing directly does not necessarily leave a saved PDF in Downloads.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-what-settings-keep-the-label-the-correct-size","title":"What settings keep the label the correct size?","html":"<p>Use Actual Size or 100% and disable automatic Fit, Shrink or Scale to fit. For a Composer sheet, select A4. If you insert a PNG into another program, first set the artwork’s width and height to the intended dimensions: 100% print scaling cannot fix an already incorrectly sized image.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-does-clpeasy-check-font-size-and-whether-everything-fits","title":"Does CLPeasy check font size and whether everything fits?","html":"<p>The Builder checks its supported size and layout limits and can block export when content does not fit. Resolve the warning in CLPeasy. Do not remove required information, shrink the downloaded artwork or redraw hazard text elsewhere to work around a block. A digital check cannot verify your printer’s actual output.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-is-a-52-mm-circle-always-the-legal-minimum","title":"Is a 52 mm circle always the legal minimum?","html":"<p>Do not treat one software preset or limit as a universal legal minimum. The applicable requirements depend on the label, packaging and information involved. CLPeasy applies its supported size rules; your print must preserve the chosen dimensions and remain readable.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-print-just-one-label-on-a4","title":"Can I print just one label on A4?","html":"<p>Yes. Save the reviewed label, open Print Sheet Composer and add quantity one. Check where it sits in the preview and whether that position matches your physical stock. You can leave the other positions blank. See the one-label guide.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":"single label a4"},
    {"id":"print-can-different-fragrances-share-one-sheet","title":"Can different fragrances share one sheet?","html":"<p>Use the Composer to add saved designs and their quantities. Check the preview, sheet fit and actual saved label sizes. A fixed die-cut sheet needs every design to match the positions and dimensions of that stock; different label sizes are not automatically compatible.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-reuse-a-partly-used-sticker-sheet","title":"Can I reuse a partly used sticker sheet?","html":"<p>Only if the stock and printer manufacturers permit feeding it again. The Composer’s already-used count skips positions from the start of its filling sequence; it is not an arbitrary map of missing stickers. Confirm that the skipped positions match your actual sheet and its feed orientation. Never shrink the artwork to correct alignment.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-do-i-need-a-cricut","title":"Do I need a Cricut?","html":"<p>No. You can use blank printable adhesive sheets and cut by hand, or matching pre-cut stock. For the Cricut Maker/Explore/Joy Xtra Print Then Cut route described here, a separate compatible printer prints the artwork and the Cricut cuts it.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-should-i-upload-the-full-a4-pdf-to-cricut","title":"Should I upload the full A4 PDF to Cricut?","html":"<p>For the workflow in this guide, use each individual PNG, including files extracted from a Composer ZIP. A combined A4 sheet is not an automatically separated collection of label cut shapes. Let Design Space prepare its own Print Then Cut layout and sensor markings.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-upload-my-svg-to-design-space","title":"Can I upload my SVG to Design Space?","html":"<p>Check compatibility before using it. Design Space does not accept editable text or certain embedded image content inside SVG uploads. If text, pictograms or layout change, stop and use the individual PNG route. Direct CLPeasy SVG import is not independently verified with CLPeasy files.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-does-the-dashed-cut-border-print","title":"Does the dashed cut border print?","html":"<p>The current Builder help says the optional cut guide is part of the downloaded artwork and does print. Use Hide border in Step 1 if you do not want it. It is not a Cricut registration mark or a guarantee of a machine cut path.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-where-have-my-downloads-gone","title":"Where have my downloads gone?","html":"<p>Start with your browser’s Downloads list and use Show in folder or the equivalent. On Windows, also check File Explorer → Downloads; on Mac, check Finder → Downloads or your chosen save location. A manually saved PDF may be wherever you selected in the save dialog. [F1–F3]</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-will-labels-i-save-appear-on-my-other-device","title":"Will labels I save appear on my other device?","html":"<p>CLPeasy’s saved label designs are kept in the browser where you save them. They are not automatically synchronised across devices. Keep copies of your final files and the source documentation. Transfer the exported file if you want to print from another computer.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-print-from-my-phone","title":"Can I print from my phone?","html":"<p>You can prepare and download files on supported mobile browsers. Find the saved file using the relevant Files/downloads location. An iPhone/iPad can use a compatible AirPrint printer, but available print controls vary. If you cannot confirm the physical size, use a computer and a viewer with explicit scaling controls.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-can-i-use-a-trial-print-on-products-i-sell","title":"Can I use a trial print on products I sell?","html":"<p>Use watermarked trial output to try the workflow and check sizing. For clean label files, use a paid option. Always review the information and the physical print before applying a label to a product for sale.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-what-if-my-print-is-blurry-missing-a-symbol-or-the-wrong-siz","title":"What if my print is blurry, missing a symbol or the wrong size?","html":"<p>Pause before using it. Check the original preview, file type, colour/quality settings, scale and intended dimensions. Reprint a paper test after correcting the cause. Do not try to hide an export or printing problem by omitting part of the safety information.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-when-should-i-contact-support","title":"When should I contact support?","html":"<p>Contact support@clpeasy.com if you need help with the Builder, extraction, downloads, saved labels or print layout. Include the file type, intended dimensions, device/browser, printer and a description or photo of the issue. Do not include passwords or payment details. Classification decisions and product safety assessment need appropriate expertise outside software support.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#faq","label":"Printing and cutting guide"}],"keywords":""},
    {"id":"print-route-one","title":"Print one label on an A4 sheet","html":"<p>Use this route when you want one label positioned on a normal A4 printable sheet or on matching pre-cut stock.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#one","label":"Open the step-by-step guide"}],"keywords":""},
    {"id":"print-route-sheets","title":"Print repeated or mixed A4 labels","html":"<p>Use the Composer for a batch of one fragrance or several saved fragrance labels on the same sheet.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#sheets","label":"Open the step-by-step guide"}],"keywords":""},
    {"id":"print-route-pdf","title":"Print an individual PDF label","html":"<p>Use this route when you want a single label-sized print view or a PDF to save for later. For placement on pre-cut A4 stock, use the Composer route instead.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#pdf","label":"Open the step-by-step guide"}],"keywords":""},
    {"id":"print-route-png","title":"Print a PNG through other software","html":"<p>Use this route when your chosen layout program needs an image. The key is setting its physical size after import.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#png","label":"Open the step-by-step guide"}],"keywords":""},
    {"id":"print-route-cricut","title":"Cricut: print and cut individual PNGs","html":"<p>For the Maker, Explore and Joy Xtra Print Then Cut workflow: use a compatible separate colour printer, then let the Cricut cut the outline.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#cricut","label":"Open the step-by-step guide"}],"keywords":"cricut cutting machine print then cut silhouette design space"},
    {"id":"print-route-svg","title":"SVG: compatibility and safe alternatives","html":"<p>SVG is useful in compatible design software, but the file type alone does not guarantee a correct Cricut import.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#svg","label":"Open the step-by-step guide"}],"keywords":"svg vector cutting software"},
    {"id":"print-route-mobile","title":"Find and print files on a phone or tablet","html":"<p>Start with the same reviewed label. Then check where the browser saved your file and whether the printing app preserves its size.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#mobile","label":"Open the step-by-step guide"}],"keywords":"phone tablet iphone ipad android"},
    {"id":"print-route-checks","title":"Check, cut and apply your printed labels","html":"<p>Use this after every new setup, material or workflow change. A paper test helps avoid wasting adhesive stock.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#checks","label":"Open the step-by-step guide"}],"keywords":""},
    {"id":"print-route-company","title":"Send your label to a print company","html":"<p>Create and download your label in CLPeasy, then arrange printing directly with a company of your choice. CLPeasy provides the software; the company you choose supplies the physical labels.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#company","label":"Open the step-by-step guide"}],"keywords":"print shop printing company no printer"},
    {"id":"print-route-files","title":"Choose, download and find your file","html":"<p>PDF, PNG, SVG and ZIP take different routes. Use the file that matches what you want to do.</p>","source":"printing","links":[{"href":"printing-and-cutting.html#files","label":"Open the step-by-step guide"}],"keywords":""},
    {"id":"kb-what-is-clp","title":"What is CLP?","html":"<p>Classification, Labelling and Packaging — the legal framework requiring hazard communication on products containing chemicals.</p><p>Covered on the Knowledge Base page: What CLP means and how it works.</p>","source":"knowledge","topic":"what-is-clp","links":[{"href":"knowledge.html#what-is-clp","label":"Read this topic in the Knowledge Base"}],"keywords":"what is clp do i need a label"},
    {"id":"kb-uk-clp","title":"UK CLP — Great Britain GB","html":"<p>England, Scotland and Wales follow retained EU law via the European Union (Withdrawal) Act 2018, administered by the HSE.</p><p>Covered on the Knowledge Base page: UK CLP details — differences from EU CLP.</p>","source":"knowledge","topic":"uk-clp","links":[{"href":"knowledge.html#uk-clp","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-eu-clp","title":"EU CLP — Regulation (EC) No 1272/2008 EU","html":"<p>CLPeasy currently focuses on Great Britain. EU requirements can differ and should be checked separately using current official guidance.</p><p>Covered on the Knowledge Base page: EU CLP full details — selling into the EU.</p>","source":"knowledge","topic":"eu-clp","links":[{"href":"knowledge.html#eu-clp","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-northern-ireland","title":"Northern Ireland — Windsor Framework EU CLP","html":"<p>Northern Ireland follows EU CLP — not UK CLP — under the Windsor Framework.</p><p>Covered on the Knowledge Base page: Practical guidance for selling into Northern Ireland.</p>","source":"knowledge","topic":"northern-ireland","links":[{"href":"knowledge.html#northern-ireland","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-label-elements","title":"What must go on a CLP label?","html":"<p>Depending on the classification, a GB CLP label may need the following elements. Verify current requirements against authoritative guidance.</p><p>Covered on the Knowledge Base page: View all 10 required label elements.</p>","source":"knowledge","topic":"label-elements","links":[{"href":"knowledge.html#label-elements","label":"Read this topic in the Knowledge Base"}],"keywords":"what goes on a label required elements must include"},
    {"id":"kb-h-statements","title":"H & P Statements","html":"<p>Standardised codes and phrases that describe hazards (H) and safe handling instructions (P). Hazard statements are found in Section 2.2 (Label elements) of your SDS. Copy that complete section into Smart Paste and review the extracted information against the source document.</p><p>Covered on the Knowledge Base page: Common H statements for product makers; Why CLPeasy uses your own SDS rather than a stored list.</p>","source":"knowledge","topic":"h-statements","links":[{"href":"knowledge.html#h-statements","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-euh208","title":"EUH208 & Sensitisers","html":"<p>If your fragrance contains classified skin sensitisers above threshold, EUH208 must appear on your label.</p><p>Covered on the Knowledge Base page: Common sensitisers found in product fragrances.</p>","source":"knowledge","topic":"euh208","links":[{"href":"knowledge.html#euh208","label":"Read this topic in the Knowledge Base"}],"keywords":"euh208 allergen sensitiser"},
    {"id":"kb-reach","title":"REACH Regulation UKEU","html":"<p>Governs chemical substances. As a product maker you are typically a downstream user — your fragrance supplier handles REACH registration.</p><p>Covered on the Knowledge Base page: What REACH means for product makers.</p>","source":"knowledge","topic":"reach","links":[{"href":"knowledge.html#reach","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-gpsr","title":"Product safety in Great Britain","html":"<p>GB consumer-product safety duties are separate from CLP label creation. Read the GB product-safety guidance and the candle guide linked below. EU and Northern Ireland requirements must be checked separately.</p><p>Covered on the Knowledge Base page: What GPSR requires for product makers.</p>","source":"knowledge","topic":"gpsr","links":[{"href":"knowledge.html#gpsr","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-ifra","title":"IFRA Standards Global","html":"<p>International Fragrance Association standards set maximum usage levels for fragrance ingredients by product category.</p><p>Covered on the Knowledge Base page: IFRA, product makers and how to get certificates.</p>","source":"knowledge","topic":"ifra","links":[{"href":"knowledge.html#ifra","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-global-clp","title":"International chemical-labelling reference Outside Great Britain","html":"<p>General reference information for makers researching requirements outside Great Britain. Jurisdictions implement chemical-labelling rules differently, so always verify the rules for the market where you supply.</p><p>Covered on the Knowledge Base page: International chemical-labelling reference — 12 markets at a glance.</p>","source":"knowledge","topic":"global-clp","links":[{"href":"knowledge.html#global-clp","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"kb-blended","title":"Blended Fragrances — What You Need to Know","html":"<p>Combining fragrance oils creates a new mixture. Your label must be based on classification information for your finished product, not on the individual oils’ safety data sheets.</p><p>Covered on the Knowledge Base page: UK legislation  guidance.</p>","source":"knowledge","topic":"blended","links":[{"href":"knowledge.html#blended","label":"Read this topic in the Knowledge Base"}],"keywords":"blend blended mix mixing combine fragrance oils"},
    {"id":"kb-official-links","title":"Official GB CLP & Reference Links","html":"<p>Authoritative GB CLP sources first, followed by clearly separated EU and international reference material.</p><p>Covered on the Knowledge Base page: EU legislation  guidance; Global resources; Industry bodies  product specific guidance.</p>","source":"knowledge","topic":"official-links","links":[{"href":"knowledge.html#official-links","label":"Read this topic in the Knowledge Base"}],"keywords":""},
    {"id":"support-before-you-contact-us","title":"Before you contact us","html":"<p>For a display or download problem, try refreshing the page and checking that you're signed into the correct account. Include your device, browser and any error message when you contact us. You can contact us even if you haven't tried these checks.</p><p>Saved labels are stored in your browser. A private window or a different browser won't show that saved library. Please don't clear your browser's site data as a troubleshooting step without first preserving anything you need.</p>","source":"support","links":[{"href":"support.html","label":"Support page"}],"keywords":""},
    {"id":"support-something-missing-after-smart-paste","title":"Something missing after Smart Paste?","html":"<p>Use the complete Section 2.2 (Label elements) from the current SDS applicable to your product, and compare the extracted result with that section. If anything is missing or different, pause before using the label and contact support. The Builder does not provide manual hazard entry or overrides. Labels saved earlier can still be printed with their hazard information locked; to change it, clear the hazard data and use Smart Paste.</p>","source":"support","links":[{"href":"support.html","label":"Support page"}],"keywords":""},
    {"id":"compliance-clear-about-what-clpeasy-does","title":"Clear about what CLPeasy does","html":"<p>CLPeasy® helps makers create CLP Ready labels for the Great Britain market: England, Scotland and Wales. It extracts label information from suitable SDS documentation and formats it for review and printing.</p><p>“CLP Ready” describes our label-building service. It is not a certification, regulatory approval or guarantee that a product or label meets every legal requirement.</p>","source":"compliance","links":[{"href":"compliance.html","label":"Compliance & Transparency"}],"keywords":"what does clpeasy do about"},
    {"id":"compliance-classification-comes-before-label-creation","title":"Classification comes before label creation","html":"<p>Classification establishes a product's chemical hazards. Label creation communicates the required information for that product.</p><p>CLPeasy performs the label-building step. It does not independently classify finished mixtures, calculate classifications for custom fragrance blends, or combine multiple SDSs. Entering a fragrance percentage does not make CLPeasy recalculate the classification.</p>","source":"compliance","links":[{"href":"compliance.html","label":"Compliance & Transparency"}],"keywords":""},
    {"id":"compliance-software-checks-have-limits","title":"Software checks have limits","html":"<p>CLPeasy's checks help identify issues within its label-building workflow. Passing those checks does not establish the correct chemical classification or confirm that all legal requirements have been met.</p><p>The Builder does not allow manual entry or overriding of H-statements, P-statements, sensitisers or hazard classifications. Report an extraction problem to support rather than altering hazard information elsewhere to work around it.</p>","source":"compliance","links":[{"href":"compliance.html","label":"Compliance & Transparency"}],"keywords":""},
    {"id":"compliance-candle-safety-is-a-separate-task","title":"Candle safety is a separate task","html":"<p>A CLP label communicates chemical hazard information. It does not demonstrate safe burning performance. Candle-care symbols do not replace product safety assessment, testing or appropriate instructions.</p><p>CLPeasy does not carry out candle testing or certify product safety. Read <a href=\"combining-fragrance-oils.html\">Combining fragrance oils: where to start</a> for an introduction to these separate steps.</p>","source":"compliance","links":[{"href":"compliance.html","label":"Compliance & Transparency"}],"keywords":""},
    {"id":"oils-can-i-combine-the-labels-from-the-individual-oils","title":"Can I combine the labels from the individual oils?","html":"<p>Simply collecting the statements from each oil does not establish the correct label for the finished blend. Nor should you choose whichever oil seems most hazardous and copy its label.</p><p>The finished formulation matters, including the amounts of each oil and the other ingredients. Using just one fragrance oil also requires information appropriate to the finished product, rather than assuming the concentrated oil's label applies unchanged.</p>","source":"combining-fragrance-oils","links":[{"href":"combining-fragrance-oils.html","label":"Combining fragrance oils guide"}],"keywords":"combine two fragrance oils blend mix sds"},
    {"id":"oils-where-does-clpeasy-fit-in","title":"Where does CLPeasy fit in?","html":"<p>CLPeasy helps with label creation once suitable documentation is available. It cannot combine ingredient SDSs or calculate your blend's classification.</p><p>The current Builder uses SDS extraction. You need suitable SDS documentation with Section 2.2 covering the finished formulation. Paste that section and review the result. If you only have a report or a list of hazard statements, it cannot be manually entered into the Builder as hazard data. Contact support about document-format or extraction questions.</p>","source":"combining-fragrance-oils","links":[{"href":"combining-fragrance-oils.html","label":"Combining fragrance oils guide"}],"keywords":""},
    {"id":"guide-printing-route","title":"Choosing a printing route","source":"guide","html":"<p><strong>Neither is the default for everyone</strong> — choose the route that matches what you are printing:</p>\n<ul><li>one individual label → ▣ PDF: an individual label file at its exact size (opens for printing or saving as PDF)</li>\n<li>several labels arranged on A4 → Print Sheet Composer: save each label, choose how many of each, and print the A4 sheet</li>\n<li>design or cutting-machine workflow → ⬡ SVG, or the Composer's \"Download for cutting machine\" PNGs</li></ul>\n<p>⬇ PNG is a high-resolution image (for example for Canva). A PNG does not store a print size, so the app used to print it may choose its own size.</p>\n<p>Print at <strong>Actual Size / 100%</strong> and turn off Fit to page, Shrink or Scale to fit. The first time, test on ordinary paper and measure a label with a ruler.</p>","links":[{"href":"printing-and-cutting.html","label":"Printing and cutting guide"}],"keywords":"print printing route which file format pdf png svg a4 sheet single one label how do i print"},
    {"id":"guide-print-shop","title":"Sending labels to a print company","source":"guide","html":"<p>CLPeasy has no dedicated print-shop file with bleed or crop marks. The ▣ PDF is the exact label size without bleed, so ask the print company what file they need.</p>","links":[{"href":"printing-and-cutting.html#company","label":"No printer at home?"}],"keywords":"print shop printing company professional printer bleed crop marks vistaprint send away"},
    {"id":"guide-signal-word","title":"Which signal word should my label use?","source":"guide","guard":"signal","html":"<p>CLPeasy doesn't choose a signal word for you. The Builder uses the signal word stated in <strong>Section 2.2</strong> of the SDS you paste into Smart Paste (for example \"Signal word: Warning\").</p>\n<p>If the Builder can't read the supplier's signal word, and the hazard information on the SDS means the label needs one, it asks you to review it before you can download: check that the pasted Section 2.2 includes the supplier's \"Signal word\" line. CLPeasy never fills in a signal word itself. If the result differs from the applicable SDS, contact support before using the label.</p>","links":[{"href":"faq.html","label":"FAQ: Which SDS should I use?"},{"href":"support.html","label":"Contact support"}],"keywords":"signal word warning danger which word"},
    {"id":"guide-no-classification","title":"Can CLPeasy tell me my hazards or classification?","source":"guide","guard":"classify","html":"<p>No. CLPeasy's guidance only explains how to use CLPeasy. It never suggests hazard statements, precautionary statements, pictograms, signal words or classifications.</p>\n<p>CLPeasy extracts and formats label information from suitable SDS documentation. It does not independently classify finished mixtures or recalculate hazards. Paste <strong>Section 2.2 — Label elements</strong> of the SDS for your product into Smart Paste in Step 3, then check every extracted code, pictogram and sensitiser against the SDS.</p>","links":[{"href":"compliance.html","label":"Compliance & Transparency"},{"href":"faq.html","label":"FAQ"}],"keywords":"classify classification hazard statements precautionary pictograms tell me hazards which h statements"},
    {"id":"guide-why-blocked","title":"Why can't I download my label?","source":"guide","html":"<p>Downloads unlock in Step 5 once the label is complete. Depending on your label, the Builder checks that:</p>\n<ul><li>the required product, hazard and business details are filled in</li>\n<li>the hazard information from Smart Paste has been reviewed, if the Builder asked you to review it</li>\n<li>the supplier document confirmation in Step 3 is complete, if the Builder asks you for it</li>\n<li>the complete label fits at a readable size</li>\n<li>you have ticked the verification checkbox in Step 5 to confirm you have checked all data against your SDS</li></ul>\n<p>When something is still needed, the Builder explains it. Some messages appear in Step 5 above the download buttons, and others appear in the step concerned. If you ask \"Why can't I download?\" here while you're in Step 5, Guide Me shows the Builder's current message.</p>","links":[],"keywords":"download blocked cannot download greyed disabled locked why won't download"}
  ] };
  if (typeof module !== 'undefined' && module.exports) module.exports = content;
  else root.CLPEASY_GUIDE_CONTENT = content;
})(this);
